using System.ComponentModel.DataAnnotations;using Essco.Application.Liquidations;using Essco.Application.Security;using Essco.Domain.Liquidations;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
namespace Essco.Web.Pages.Liquidations;[Authorize(Policy=Permissions.LiquidationDifferences)]public sealed class ExpensesModel(LiquidationExpenseService service):PageModel
{[BindProperty(SupportsGet=true)]public FilterModel Filter{get;set;}=new();[BindProperty]public InputModel Input{get;set;}=new();public IReadOnlyCollection<LiquidationExpense>Items{get;private set;}=[];[TempData]public string? StatusMessage{get;set;}public async Task OnGetAsync(int? edit,CancellationToken t){await Load(t);if(edit is not null){var x=Items.SingleOrDefault(x=>x.Id==edit);if(x is not null)Input=InputModel.From(x);}}public async Task<IActionResult>OnPostSaveAsync(CancellationToken t){if(ModelState.IsValid){var r=await service.SaveAsync(Input.Domain(),Input.IsNew,t);if(r.Succeeded){StatusMessage=$"Gasto {r.Id} guardado.";return RedirectToPage();}foreach(var e in r.Errors)ModelState.AddModelError("",e);}await Load(t);return Page();}public async Task<IActionResult>OnPostAnnulAsync(int id,CancellationToken t){StatusMessage=await service.AnnulAsync(id,t)?$"Gasto {id} anulado.":"No fue posible anular.";return RedirectToPage();}private async Task Load(CancellationToken t)=>Items=await service.ListAsync(Filter.Domain(),t);
 public sealed class FilterModel{public string? Type{get;set;}public int? Liquidation{get;set;}public string? Employee{get;set;}[DataType(DataType.Date)]public DateOnly? From{get;set;}[DataType(DataType.Date)]public DateOnly? To{get;set;}public bool IncludeAnnulled{get;set;}public LiquidationExpenseFilter Domain()=>new(Type,Liquidation,Employee,From,To,IncludeAnnulled:IncludeAnnulled);}
 public sealed class InputModel{public bool IsNew{get;set;}=true;public int Id{get;set;}[Required]public string DocumentNumber{get;set;}="";[Required]public string Category{get;set;}="";[Range(typeof(decimal),"0.01","999999999999")]public decimal Amount{get;set;}public string Description{get;set;}="";public int? LiquidationNumber{get;set;}[Required]public string LiquidationType{get;set;}="AGENTES";[Required]public string EmployeeCode{get;set;}="";[DataType(DataType.Date)]public DateOnly Date{get;set;}=DateOnly.FromDateTime(DateTime.Today);public bool IsElectronicInvoice{get;set;}public string SupplierCode{get;set;}="";public bool IncludeInLiquidation{get;set;}=true;public LiquidationExpense Domain()=>new(){Id=Id,DocumentNumber=DocumentNumber,Category=Category,Amount=Amount,Description=Description,LiquidationNumber=LiquidationNumber,LiquidationType=LiquidationType,EmployeeCode=EmployeeCode,Date=Date,IsElectronicInvoice=IsElectronicInvoice,SupplierCode=SupplierCode,IncludeInLiquidation=IncludeInLiquidation,HaciendaStatus=""};public static InputModel From(LiquidationExpense x)=>new(){IsNew=false,Id=x.Id,DocumentNumber=x.DocumentNumber,Category=x.Category,Amount=x.Amount,Description=x.Description,LiquidationNumber=x.LiquidationNumber,LiquidationType=x.LiquidationType,EmployeeCode=x.EmployeeCode,Date=x.Date,IsElectronicInvoice=x.IsElectronicInvoice,SupplierCode=x.SupplierCode,IncludeInLiquidation=x.IncludeInLiquidation};}}
